import sailpoint.object.QueryOptions;

int TOTAL_SORTS = 100;
Class SP_CLASS = sailpoint.object.CertificationItem.class;

List allObjects = context.getObjects(SP_CLASS, new QueryOptions());
for (int i = 0; i < TOTAL_SORTS; i++) {
    log.warn("Iteration: " + i);
    // shuffle it
    Collections.shuffle(allObjects);

    // sort it
    Collections.sort(allObjects);
}
return "That was really fun.";
